/* ===== about-vava-en.html ===== */

@font-face{
      font-family:"VAVA Display";
      src:url(data:font/woff2;base64,) format("woff2");
      font-weight:500;
      font-style:normal;
      font-display:swap;
    }
@font-face{
      font-family:"VAVA Body";
      src:url(data:font/woff2;base64,) format("woff2");
      font-weight:400;
      font-style:normal;
      font-display:swap;
    }
html[data-page="about-vava-en.html"]{
  --mist:#99B4AA;--olive:#6B6D43;--sage:#ABA66F;--coral:#CF7D65;--blush:#E1B8A2;--cream:#F2DEC7;--paper:#fffaf2;--ink:#47443a;--muted:#777168;--line:rgba(107,109,67,.18);--header:rgba(255,250,242,.72);--shadow:0 24px 80px rgba(73,65,45,.10);
}
html[data-page="about-vava-en.html"] *{box-sizing:border-box}
html[data-page="about-vava-en.html"]{scroll-behavior:smooth}
html[data-page="about-vava-en.html"] body{margin:0;min-height:100%;direction:ltr;background:radial-gradient(circle at 12% 8%, rgba(225,184,162,.20), transparent 28%),radial-gradient(circle at 90% 0%, rgba(153,180,170,.20), transparent 30%),var(--paper);color:var(--ink);font-family:"VAVA Text","IBM Plex Sans Arabic","Noto Sans Arabic",Tahoma,Arial,sans-serif;overflow-x:hidden}
html[data-page="about-vava-en.html"] body:before{content:"";position:fixed;inset:0;pointer-events:none;z-index:-2;background-image:radial-gradient(rgba(107,109,67,.11) .75px, transparent .85px);background-size:18px 18px;opacity:.34;mask-image:linear-gradient(to bottom,transparent,black 12%,black 86%,transparent)}
html[data-page="about-vava-en.html"] body:after{content:"";position:fixed;left:-8vw;bottom:-12vw;width:44vw;height:44vw;border-radius:50%;background:rgba(225,184,162,.20);z-index:-3}
html[data-page="about-vava-en.html"] .fixed-header{position:fixed;z-index:50;top:18px;left:24px;right:24px;height:74px;display:flex;align-items:center;justify-content:space-between;padding:0 22px;border:1px solid rgba(255,255,255,.65);border-bottom-color:var(--line);border-radius:30px;background:var(--header);backdrop-filter:blur(18px) saturate(1.1);box-shadow:0 16px 50px rgba(63,63,44,.08)}
html[data-page="about-vava-en.html"] .logo{height:62px;width:148px;object-fit:contain;mix-blend-mode:multiply;display:block}
html[data-page="about-vava-en.html"] .brand-link{display:flex;align-items:center;text-decoration:none}
html[data-page="about-vava-en.html"] nav{display:flex;align-items:center;gap:34px;font-size:15px;letter-spacing:.01em}
html[data-page="about-vava-en.html"] nav a{color:var(--ink);text-decoration:none;position:relative;padding:10px 0;opacity:.82;transition:.28s ease;white-space:nowrap}
html[data-page="about-vava-en.html"] nav a:hover,html[data-page="about-vava-en.html"] nav a.active{color:var(--coral);opacity:1}
html[data-page="about-vava-en.html"] nav a.active:after{content:"";position:absolute;bottom:0;right:50%;transform:translateX(50%);width:5px;height:5px;border-radius:50%;background:var(--coral)}
html[data-page="about-vava-en.html"] .header-tools{display:flex;align-items:center;gap:10px;color:var(--olive);font-size:15px;direction:ltr}
html[data-page="about-vava-en.html"] .language-icon{width:26px;height:26px;border:1px solid var(--line);border-radius:50%;display:grid;place-items:center;color:var(--olive);font-size:15px;background:rgba(255,255,255,.35)}
html[data-page="about-vava-en.html"] .lang{font-size:13px;letter-spacing:.08em;color:var(--ink)}
html[data-page="about-vava-en.html"] .burger{display:none;width:42px;height:42px;border:1px solid var(--line);border-radius:16px;background:rgba(255,255,255,.42);align-items:center;justify-content:center}
html[data-page="about-vava-en.html"] .burger span{width:18px;height:1px;background:var(--olive);box-shadow:0 6px 0 var(--olive),0 -6px 0 var(--olive)}
html[data-page="about-vava-en.html"] main{position:relative;padding-top:118px;overflow:hidden}
html[data-page="about-vava-en.html"] .leaf-line{position:absolute;width:150px;height:150px;opacity:.20;z-index:-1;border:1px solid rgba(207,125,101,.55);border-radius:80% 0 80% 0;transform:rotate(35deg)}
html[data-page="about-vava-en.html"] .blob{position:absolute;border-radius:48% 52% 58% 42%;filter:blur(.2px);opacity:.72;z-index:-2}
html[data-page="about-vava-en.html"] .blob.sage{width:38vw;height:34vw;left:-10vw;top:12vh;background:rgba(153,180,170,.18)}
html[data-page="about-vava-en.html"] .blob.cream{width:44vw;height:25vw;right:-8vw;top:24vh;background:rgba(242,222,199,.42)}
html[data-page="about-vava-en.html"] .section{position:relative;min-height:86vh;padding:clamp(72px,9vw,135px) clamp(24px,6vw,92px);display:flex;align-items:center}
html[data-page="about-vava-en.html"] .container{width:min(1180px,100%);margin:auto;position:relative}
html[data-page="about-vava-en.html"] .hero-grid,html[data-page="about-vava-en.html"] .split-grid{display:grid;grid-template-columns:1fr 1fr;gap:clamp(38px,6vw,90px);align-items:center}
html[data-page="about-vava-en.html"] .hero-copy{max-width:680px}
html[data-page="about-vava-en.html"] .eyebrow{font-family:Georgia,"Times New Roman",serif;color:var(--olive);letter-spacing:.08em;font-size:16px;margin-bottom:12px}
html[data-page="about-vava-en.html"] h1,html[data-page="about-vava-en.html"] h2,html[data-page="about-vava-en.html"] h3{font-family:"VAVA Display","Noto Kufi Arabic",serif;color:#4b473b;font-weight:500;line-height:1.25;margin:0}
html[data-page="about-vava-en.html"] h1{font-size:clamp(48px,7vw,92px);letter-spacing:-.03em}
html[data-page="about-vava-en.html"] h2{font-size:clamp(34px,4.6vw,64px)}
html[data-page="about-vava-en.html"] h3{font-size:clamp(24px,2.7vw,36px)}
html[data-page="about-vava-en.html"] p{font-size:clamp(17px,1.35vw,21px);line-height:2.15;color:#575247;margin:18px 0}
html[data-page="about-vava-en.html"] .small{font-size:clamp(15px,1.08vw,17px);line-height:2;color:var(--muted)}
html[data-page="about-vava-en.html"] .btn-row{display:flex;gap:16px;flex-wrap:wrap;margin-top:30px;align-items:center}
html[data-page="about-vava-en.html"] .btn{border:1px solid transparent;border-radius:16px;padding:14px 34px;min-width:176px;text-align:center;text-decoration:none;font-size:16px;transition:.35s ease;cursor:pointer;box-shadow:0 12px 34px rgba(79,70,51,.08);display:inline-block}
html[data-page="about-vava-en.html"] .btn.primary{background:var(--olive);color:white}
html[data-page="about-vava-en.html"] .btn.secondary{background:rgba(255,255,255,.52);color:var(--coral);border-color:rgba(207,125,101,.45)}
html[data-page="about-vava-en.html"] .btn.coral{background:var(--coral);color:white}
html[data-page="about-vava-en.html"] .btn:hover{transform:translateY(-3px)}
html[data-page="about-vava-en.html"] .visual-card{min-height:430px;border-radius:44px;background-size:cover;background-position:center;box-shadow:var(--shadow);border:1px solid rgba(255,255,255,.68);position:relative;overflow:hidden}
html[data-page="about-vava-en.html"] .visual-card:after{content:"";position:absolute;inset:0;background:linear-gradient(135deg,rgba(255,250,242,.18),rgba(107,109,67,.05));pointer-events:none}
html[data-page="about-vava-en.html"] .text-panel{background:rgba(255,250,242,.64);border:1px solid var(--line);border-radius:40px;padding:clamp(28px,4vw,54px);box-shadow:0 16px 60px rgba(85,78,59,.055);backdrop-filter:blur(10px)}
html[data-page="about-vava-en.html"] .open-text{max-width:840px;margin-inline:auto;text-align:center}
html[data-page="about-vava-en.html"] .cards{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-top:38px}
html[data-page="about-vava-en.html"] .card{background:rgba(255,250,242,.62);border:1px solid var(--line);border-radius:30px;padding:30px;box-shadow:0 12px 45px rgba(85,78,59,.045)}
html[data-page="about-vava-en.html"] .card .tag{display:inline-flex;margin-bottom:18px;padding:7px 13px;border-radius:999px;background:rgba(171,166,111,.16);color:var(--olive);font-size:13px}
html[data-page="about-vava-en.html"] .card h3{font-size:clamp(22px,2vw,30px)}
html[data-page="about-vava-en.html"] .product-grid,html[data-page="about-vava-en.html"] .journal-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin-top:36px}
html[data-page="about-vava-en.html"] .product,html[data-page="about-vava-en.html"] .journal-card{background:rgba(255,250,242,.68);border:1px solid var(--line);border-radius:28px;padding:24px;min-height:190px;box-shadow:0 12px 45px rgba(85,78,59,.04)}
html[data-page="about-vava-en.html"] .product .num{color:var(--coral);font-family:Georgia,serif;font-size:13px;letter-spacing:.12em}
html[data-page="about-vava-en.html"] .journal-card .thumb{height:135px;border-radius:22px;background-size:cover;background-position:center;margin-bottom:18px;border:1px solid rgba(255,255,255,.55)}

/* About VAVA breathable editorial layout */
html[data-page="about-vava-en.html"] .about-page main{background:
  radial-gradient(circle at 12% 20%,rgba(242,222,199,.34),transparent 25%),
  radial-gradient(circle at 86% 10%,rgba(153,180,170,.13),transparent 28%);
}
html[data-page="about-vava-en.html"] .about-page .section{align-items:center}
html[data-page="about-vava-en.html"] .about-hero-section{min-height:calc(100vh - 80px);padding-top:clamp(82px,10vw,142px)}
html[data-page="about-vava-en.html"] .about-hero-panel{width:min(1040px,100%);margin:auto;text-align:center;position:relative;padding:clamp(36px,6vw,84px) clamp(20px,5vw,78px);border-radius:56px;background:linear-gradient(135deg,rgba(255,250,242,.56),rgba(255,250,242,.22));border:1px solid rgba(132,124,94,.12);box-shadow:0 22px 90px rgba(85,78,59,.045);backdrop-filter:blur(7px);overflow:hidden}
html[data-page="about-vava-en.html"] .about-hero-panel:before{content:"";position:absolute;inset:auto -8% -26% auto;width:48%;height:62%;border-radius:55% 45% 50% 50%;background:rgba(171,166,111,.11);z-index:-1}
html[data-page="about-vava-en.html"] .about-hero-panel:after{content:"";position:absolute;inset:10% auto auto -5%;width:220px;height:300px;border:1px solid rgba(207,125,101,.11);border-radius:60% 40% 65% 35%;transform:rotate(-24deg);z-index:-1}
html[data-page="about-vava-en.html"] .about-hero-panel h1{font-size:clamp(54px,8vw,108px);margin-bottom:18px}
html[data-page="about-vava-en.html"] .about-hero-lead{max-width:820px;margin:0 auto 26px;font-size:clamp(20px,1.75vw,27px);line-height:2.05;color:#4f4a3e}
html[data-page="about-vava-en.html"] .about-hero-mini{max-width:760px;margin-inline:auto;color:rgba(87,82,71,.72);font-size:clamp(15px,1.05vw,17px);line-height:2.05}
html[data-page="about-vava-en.html"] .about-hero-trio{display:flex;flex-wrap:wrap;gap:12px;margin:34px auto 0;max-width:760px}
html[data-page="about-vava-en.html"] .about-hero-trio span{display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto;width:auto;padding:12px 18px;border-radius:999px;background:rgba(171,166,111,.10);border:1px solid rgba(107,109,67,.10);color:rgba(87,82,71,.78);font-size:14px;white-space:nowrap}
html[data-page="about-vava-en.html"] .about-editorial{width:min(1120px,100%);margin:auto;display:grid;grid-template-columns:minmax(220px,.65fr) minmax(0,1.35fr);gap:clamp(34px,6vw,86px);align-items:start}
html[data-page="about-vava-en.html"] .about-kicker{position:sticky;top:130px;text-align:left;padding-top:18px}
html[data-page="about-vava-en.html"] .about-kicker .eyebrow{margin-bottom:12px}
html[data-page="about-vava-en.html"] .about-kicker h2{font-size:clamp(38px,4.8vw,72px)}
html[data-page="about-vava-en.html"] .about-kicker p{font-size:clamp(15px,1.05vw,17px);line-height:2;color:rgba(87,82,71,.68);max-width:290px}
html[data-page="about-vava-en.html"] .about-flow{display:grid;gap:18px}
html[data-page="about-vava-en.html"] .about-flow p{margin:0;font-size:clamp(17px,1.22vw,20px);line-height:2.08;text-align:left;max-width:740px;color:#575247}
html[data-page="about-vava-en.html"] .about-flow .soft-line{padding:24px 28px;border-radius:30px;background:rgba(255,250,242,.42);border:1px solid rgba(132,124,94,.10);box-shadow:0 12px 46px rgba(85,78,59,.035)}
html[data-page="about-vava-en.html"] .about-flow .whisper{font-size:clamp(15px,1.04vw,17px);color:rgba(87,82,71,.72);line-height:2.05;padding-inline-start:26px;border-inline-start:1px solid rgba(207,125,101,.28)}
html[data-page="about-vava-en.html"] .about-why-section{min-height:82vh}
html[data-page="about-vava-en.html"] .why-poem{width:min(1080px,100%);margin:auto;display:grid;grid-template-columns:1.05fr .95fr;gap:clamp(34px,6vw,80px);align-items:center}
html[data-page="about-vava-en.html"] .why-orb{min-height:430px;border-radius:48px;background-image:url("../images/about-why-vava.png");background-size:cover;background-position:center;border:1px solid rgba(132,124,94,.11);box-shadow:0 18px 80px rgba(85,78,59,.04);display:block;position:relative;overflow:hidden}
html[data-page="about-vava-en.html"] .why-orb:before{content:none}
html[data-page="about-vava-en.html"] .why-orb:after{content:none}
html[data-page="about-vava-en.html"] .why-copy{max-width:620px;text-align:left}
html[data-page="about-vava-en.html"] .why-copy h2{margin-bottom:22px}
html[data-page="about-vava-en.html"] .why-copy .poetic{font-size:clamp(18px,1.35vw,22px);line-height:2.18;color:#4f4a3e}
html[data-page="about-vava-en.html"] .why-copy .soft-line{margin-top:24px;padding:22px 26px;border-radius:28px;background:rgba(255,250,242,.46);border:1px solid rgba(132,124,94,.11);font-size:clamp(15px,1.04vw,17px);line-height:2;color:rgba(87,82,71,.72)}
html[data-page="about-vava-en.html"] .vision-shell{width:min(1080px,100%);margin:auto;text-align:center}
html[data-page="about-vava-en.html"] .vision-shell>p{max-width:760px;margin-inline:auto;color:rgba(87,82,71,.74)}
html[data-page="about-vava-en.html"] .vision-steps{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:42px;text-align:left}
html[data-page="about-vava-en.html"] .vision-step{border-radius:34px;padding:28px;background:rgba(255,250,242,.44);border:1px solid rgba(132,124,94,.10);box-shadow:0 14px 52px rgba(85,78,59,.035);min-height:230px}
html[data-page="about-vava-en.html"] .vision-step .num{font-family:Georgia,"Times New Roman",serif;color:var(--coral);font-size:14px;letter-spacing:.12em;direction:ltr;display:inline-block;margin-bottom:14px}
html[data-page="about-vava-en.html"] .vision-step h3{font-size:clamp(22px,2.05vw,30px);margin-bottom:12px}
html[data-page="about-vava-en.html"] .vision-step p{font-size:clamp(15px,1.02vw,17px);line-height:2;color:rgba(87,82,71,.76)}
html[data-page="about-vava-en.html"] .vision-dream{margin:26px auto 0;max-width:780px;padding:24px 30px;border-radius:32px;background:linear-gradient(135deg,rgba(171,166,111,.11),rgba(231,239,234,.20));border:1px solid rgba(107,109,67,.11);color:rgba(87,82,71,.78);font-size:clamp(15px,1.05vw,17px);line-height:2}
html[data-page="about-vava-en.html"] .about-invite-section{min-height:74vh}
html[data-page="about-vava-en.html"] .invite-panel{max-width:940px;margin:auto;text-align:center;padding:clamp(34px,5vw,72px);border-radius:52px;background:linear-gradient(135deg,rgba(255,250,242,.62),rgba(231,239,234,.34));border:1px solid rgba(132,124,94,.12);box-shadow:0 20px 82px rgba(85,78,59,.045);position:relative;overflow:hidden}
html[data-page="about-vava-en.html"] .invite-panel:after{content:"";position:absolute;left:7%;bottom:-58px;width:190px;height:250px;border:1px solid rgba(207,125,101,.13);border-radius:60% 40% 60% 40%;transform:rotate(-22deg)}
html[data-page="about-vava-en.html"] .invite-panel p{max-width:710px;margin-inline:auto}html[data-page="about-vava-en.html"] .invite-panel .btn-row{justify-content:center}
@media(max-width:900px){html[data-page="about-vava-en.html"] .about-hero-trio,html[data-page="about-vava-en.html"] .vision-steps{grid-template-columns:1fr}html[data-page="about-vava-en.html"] .about-editorial,html[data-page="about-vava-en.html"] .why-poem{grid-template-columns:1fr}html[data-page="about-vava-en.html"] .about-kicker{position:relative;top:auto;text-align:center;padding-top:0}html[data-page="about-vava-en.html"] .about-kicker p{margin-inline:auto}html[data-page="about-vava-en.html"] .about-flow p{text-align:center}html[data-page="about-vava-en.html"] .about-flow .whisper{padding-inline-start:0;border-inline-start:0;border-top:1px solid rgba(207,125,101,.20);padding-top:18px}html[data-page="about-vava-en.html"] .why-copy{text-align:center;margin:auto}html[data-page="about-vava-en.html"] .why-orb{min-height:260px}html[data-page="about-vava-en.html"] .vision-step{text-align:center}}

html[data-page="about-vava-en.html"] .footer{width:100%;padding:26px clamp(28px,5vw,70px);background:rgba(107,109,67,.94);color:white;border-radius:40px 40px 0 0;display:grid;grid-template-columns:1fr 2.1fr 1fr;align-items:center;gap:20px;min-height:150px;box-shadow:0 -20px 70px rgba(107,109,67,.16);position:relative;z-index:2}
html[data-page="about-vava-en.html"] .footer img{height:78px;width:150px;object-fit:contain;opacity:.88;display:block;background:transparent;mix-blend-mode:screen}
html[data-page="about-vava-en.html"] .footer a,html[data-page="about-vava-en.html"] .footer span,html[data-page="about-vava-en.html"] .footer-copy{color:rgba(255,255,255,.86);text-decoration:none;font-size:14px}
html[data-page="about-vava-en.html"] .footer-center{display:grid;gap:13px;justify-items:center;text-align:center;line-height:1.6}
html[data-page="about-vava-en.html"] .footer-main-links,html[data-page="about-vava-en.html"] .footer-policy-links{display:flex;align-items:center;justify-content:center;flex-wrap:wrap;column-gap:34px;row-gap:8px}
html[data-page="about-vava-en.html"] .social{display:flex;gap:10px;justify-content:flex-start;direction:ltr}
html[data-page="about-vava-en.html"] .social i{width:32px;height:32px;border:1px solid rgba(255,255,255,.36);border-radius:50%;display:grid;place-items:center;font-style:normal;font-size:13px}
html[data-page="about-vava-en.html"] .social svg{width:15px;height:15px;display:block;stroke:currentColor;stroke-width:1.65;fill:none;stroke-linecap:round;stroke-linejoin:round}
html[data-page="about-vava-en.html"] .social i[aria-label="Facebook"] svg,html[data-page="about-vava-en.html"] .social i[aria-label="YouTube"] svg{stroke:none;fill:currentColor}

html[data-page="about-vava-en.html"] .form-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:26px}
html[data-page="about-vava-en.html"] .field{display:grid;gap:8px}
html[data-page="about-vava-en.html"] .field.full{grid-column:1/-1}
html[data-page="about-vava-en.html"] label{font-size:14px;color:var(--olive)}
html[data-page="about-vava-en.html"] input,html[data-page="about-vava-en.html"] textarea{width:100%;border:1px solid var(--line);background:rgba(255,255,255,.45);border-radius:18px;padding:15px 18px;font:inherit;color:var(--ink);outline:none}
